19	// extractUsernameFromFilter extracts username from the filter string using CEL.
20	// Supported filter format: "username == 'steven'"
21	// Returns the username value and an error if the filter format is invalid.
22	func extractUsernameFromFilter(filterStr string) (string, error) {
23		filterStr = strings.TrimSpace(filterStr)
24		if filterStr == "" {
25			return "", nil
26		}
27	
28		// Create CEL environment with username variable
29		env, err := cel.NewEnv(
30			cel.Variable("username", cel.StringType),
31		)
32		if err != nil {
33			return "", errors.Wrap(err, "failed to create CEL environment")
34		}
35	
36		// Parse and check the filter expression
37		celAST, issues := env.Compile(filterStr)
38		if issues != nil && issues.Err() != nil {
39			return "", errors.Wrapf(issues.Err(), "invalid filter expression: %s", filterStr)
40		}
41	
42		// Extract username from the AST
43		username, err := extractUsernameFromAST(celAST.NativeRep().Expr())
44		if err != nil {
45			return "", err
46		}
47	
48		return username, nil
49	}
50	
51	// extractUsernameFromAST extracts the username value from a CEL AST expression.
52	func extractUsernameFromAST(expr ast.Expr) (string, error) {
53		if expr == nil {
54			return "", errors.New("empty expression")
55		}
56	
57		// Check if this is a call expression (for ==, !=, etc.)
58		if expr.Kind() != ast.CallKind {
59			return "", errors.New("filter must be a comparison expression (e.g., username == 'value')")
60		}
61	
62		call := expr.AsCall()
63	
64		// We only support == operator
65		if call.FunctionName() != "_==_" {
66			return "", errors.Errorf("unsupported operator: %s (only '==' is supported)", call.FunctionName())
67		}
68	
69		// The call should have exactly 2 arguments
70		args := call.Args()
71		if len(args) != 2 {
72			return "", errors.New("invalid comparison expression")
73		}
74	
75		// Try to extract username from either left or right side
76		if username, ok := extractUsernameFromComparison(args[0], args[1]); ok {
77			return username, nil
78		}
79		if username, ok := extractUsernameFromComparison(args[1], args[0]); ok {
80			return username, nil
81		}
82	
83		return "", errors.New("filter must compare 'username' field with a string constant")
84	}
85	
86	// extractUsernameFromComparison tries to extract username value if left is 'username' ident and right is a string constant.
87	func extractUsernameFromComparison(left, right ast.Expr) (string, bool) {
88		// Check if left side is 'username' identifier
89		if left.Kind() != ast.IdentKind {
90			return "", false
91		}
92		ident := left.AsIdent()
93		if ident != "username" {
94			return "", false
95		}
96	
97		// Right side should be a constant string
98		if right.Kind() != ast.LiteralKind {
99			return "", false
100		}
101		literal := right.AsLiteral()
102	
103		// literal is a ref.Val, we need to get the Go value
104		str, ok := literal.Value().(string)
105		if !ok || str == "" {
106			return "", false
107		}
108	
109		return str, true
110	}
